import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/launchpick.html","title":"launchpick","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":0.35,"words":104},"filePathRelative":"launchpick.md"}`),a={name:`launchpick.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="launchpick" tabindex="-1"><a class="header-anchor" href="#launchpick"><span>launchpick</span></a></h1><p><a href="./Mac.html">Mac</a>のランチャー。</p><p><a href="https://github.com/scorredoira/launchpick?utm_source=gemini" target="_blank" rel="noopener noreferrer">scorredoira/launchpick: Native macOS app launcher, window switcher, and same-app window cycler. Free and open source.</a></p><h2 id="あらすじ" tabindex="-1"><a class="header-anchor" href="#あらすじ"><span>あらすじ</span></a></h2><p>Spotlightが最近使い物にならなくなってきたので、ローカルのシェルスクリプトなどを起動する何かが欲しいと思い試してみる。</p><h2 id="インストール" tabindex="-1"><a class="header-anchor" href="#インストール"><span>インストール</span></a></h2><p>dmgを開いてApplications下にDnDして開いた所、「Launchpickはこわれているため開けません」と言われる。 設定画面のセキュリティの所にブロックしたむねもでていない。</p><p>コマンドラインから以下を実行したら開けた。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">xattr -cr /Applications/Launchpick.app</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>開いた後はアクセシビリティの設定をする。</p><h3 id="動作確認" tabindex="-1"><a class="header-anchor" href="#動作確認"><span>動作確認</span></a></h3><p>appをダブルクリックすると右上のタスクバーにアイコンが出て起動しているのが分かる。 とりあえず Cmd+Shift+Spaceでランチャーが立ち上がる。</p><h2 id="ショートカット" tabindex="-1"><a class="header-anchor" href="#ショートカット"><span>ショートカット</span></a></h2><ul><li>Cmd+Shift+Space ランチャー</li><li>Option+Tab ウィンドウ切り替え</li><li>Option+Cmd+P 同一アプリ内のウィンドウ切り替え</li></ul><h3 id="カスタマイズ" tabindex="-1"><a class="header-anchor" href="#カスタマイズ"><span>カスタマイズ</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">vi ~/.config/launchpick/config.json</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>でカスタマイズ。以下でランチャーをCmd+Spaceに出来る。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">&quot;suppressSystemShortcut&quot; : true,</span>
<span class="line">&quot;shortcut&quot;: &quot;cmd+space&quot;,</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div>`,18)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};